      nl: "Incidenten die afzonderlijk niet significant zijn, maar ten minste twee keer binnen zes maanden voorkomen, dezelfde ogenschijnlijke grondoorzaak hebben en samen aan het criterium voor financieel verlies voldoen; zij tellen als één significant incident (CIR Artikel 4).",
      fr: "Des incidents qui, pris isolément, ne sont pas importants mais qui se produisent au moins deux fois en six mois, ont la même cause apparente et remplissent ensemble le critère de perte financière ; ils comptent comme un seul incident important (CIR, article 4).",
