      de: "Die Entscheidung, ein Risiko bewusst zu tragen statt es zu beheben; nach CIR 2.1.1 akzeptiert es die Geschäftsleitung oder gegebenenfalls eine verantwortliche Person mit Befugnis zum Risikomanagement, bei angemessener Berichterstattung an die Geschäftsleitung.",
      nl: "Besluiten met een risico te leven in plaats van het te verhelpen; volgens CIR 2.1.1 aanvaardt het leidinggevend orgaan of, in voorkomend geval, een verantwoordelijke risico-eigenaar het, met passende rapportage aan het management.",
