      es: "Decidir convivir con un riesgo en lugar de corregirlo; conforme al CIR 2.1.1, lo acepta el órgano de dirección o, en su caso, un propietario del riesgo que rinda cuentas, con una información adecuada a la dirección.",
      pl: "Decyzja, by żyć z ryzykiem zamiast je usuwać; zgodnie z CIR 2.1.1 akceptuje je organ zarządzający lub, w stosownych przypadkach, odpowiedzialny właściciel ryzyka, z odpowiednim raportowaniem do kierownictwa.",
      pt: "Decidir conviver com um risco em vez de o corrigir; nos termos do CIR 2.1.1, aceitam-no o órgão de administração ou, se aplicável, um responsável pelo risco que responda por ele, com comunicação adequada à direção.",
