      nl: "De regels die het betalen aan bepaalde personen en groepen verbieden; volgens Amerikaanse regels ongeacht de bedoeling, volgens EU-regels vervalt de aansprakelijkheid alleen als u het niet wist en geen redelijke grond had om een schending te vermoeden (Verordening (EU) 2019/796 van de Raad, artikel 10(2)). De eerste juridische controle vóór elke losgeldbetaling.",
