      fr: "Les règles qui interdisent de payer certaines personnes et certains groupes ; selon les règles américaines quelle que soit l'intention, selon les règles de l'UE la responsabilité n'est écartée que si vous ne saviez pas et ne pouviez raisonnablement pas savoir (règlement (UE) 2019/796 du Conseil, article 10(2)). La première vérification juridique avant tout paiement de rançon.",
