      es: "Las normas que prohíben pagar a determinadas personas y grupos; según las normas de EE. UU. con independencia de la intención, según las normas de la UE solo se queda exento si no se sabía ni había motivos razonables para sospechar una infracción (Reglamento (UE) 2019/796 del Consejo, artículo 10(2)). La primera comprobación jurídica antes de cualquier pago de rescate.",
