      pt: "As regras que proíbem pagar a determinadas pessoas e grupos; segundo as regras dos EUA independentemente da intenção, segundo as regras da UE a responsabilidade só desaparece se não sabia nem tinha motivos razoáveis para suspeitar de uma violação (Regulamento (UE) 2019/796 do Conselho, artigo 10(2)). A primeira verificação jurídica antes de qualquer pagamento de resgate.",
